$banners=[];$q=$conn->query("SELECT * FROM banners WHERE status=1 AND banner_type='main' ORDER BY id");while($r=$q->fetch_assoc())$banners[]=$r;
$flash=$conn->query("SELECT p.*,b.name brand_name,c.name category_name FROM products p LEFT JOIN brands b ON p.brand_id=b.id LEFT JOIN categories c ON p.category_id=c.id WHERE p.sale_price>0 ORDER BY ((p.price-p.sale_price)/p.price) DESC LIMIT 6");
$hot=$conn->query("SELECT p.*,b.name brand_name,c.name category_name FROM products p LEFT JOIN brands b ON p.brand_id=b.id LEFT JOIN categories c ON p.category_id=c.id WHERE p.is_hot=1 ORDER BY p.sales_count DESC LIMIT 8");
$new=$conn->query("SELECT p.*,b.name brand_name,c.name category_name FROM products p LEFT JOIN brands b ON p.brand_id=b.id LEFT JOIN categories c ON p.category_id=c.id ORDER BY p.id DESC LIMIT 6");
$news=[];$q=$conn->query("SELECT * FROM news ORDER BY created_at DESC,id DESC LIMIT 3");while($r=$q->fetch_assoc())$news[]=$r;
$icons=['fa-laptop','fa-mobile-screen-button','fa-tablet-screen-button','fa-display','fa-keyboard','fa-wifi','fa-headphones','fa-memory'];
