<script>(function(){const h=document.getElementById('fcH'),m=document.getElementById('fcM'),s=document.getElementById('fcS');if(!h)return;function pad(n){return String(n).padStart(2,'0')}function tick(){const now=new Date();const end=new Date();end.setHours(23,59,59,999);let diff=Math.max(0,end-now);const hh=Math.floor(diff/3600000);diff-=hh*3600000;const mm=Math.floor(diff/60000);diff-=mm*60000;const ss=Math.floor(diff/1000);h.textContent=pad(hh);m.textContent=pad(mm);s.textContent=pad(ss)}tick();setInterval(tick,1000)})();</script>
<script>(function(){const banner=document.getElementById('homeBanner');if(!banner)return;const slides=[...banner.querySelectorAll('.hero-slide')],dots=[...banner.querySelectorAll('.banner-dot')];if(slides.length<2)return;let index=0;function show(i){index=i;slides.forEach((s,n)=>s.classList.toggle('active',n===i));dots.forEach((d,n)=>d.classList.toggle('active',n===i))}dots.forEach((d,i)=>d.addEventListener('click',()=>show(i)));setInterval(()=>show((index+1)%slides.length),5000)})();</script>
